  const SENT = { pyetëse: ["Ku është çanta ime?", "Sa vjeç je?", "Kur fillon mësimi?", "Kush e solli librin?", "Pse po qan bebja?"], dëftore: ["Arta lexon një libër.", "Sot bie shi.", "Gjyshi punon në kopsht.", "Lumi rrjedh qetë.", "Shkolla jonë është e madhe."], thirrmore: ["Sa bukur këndon zogu!", "Bravo, fitove!", "Oh, sa ftohtë bën!", "Sa e madhe është kalaja!", "Ua, sa borë ka rënë!"] };
  const POS3 = { emër: ["shkollë", "lumë", "libër", "gur", "qytet", "nënë", "mollë", "mal"], folje: ["shkruaj", "vrapoj", "mendoj", "lexon", "këndojmë", "luajnë", "flas", "hëngri"], mbiemër: ["i bukur", "e gjelbër", "i shpejtë", "i zgjuar", "e ëmbël", "i lartë", "e kuqe", "i vogël"] };
  const POS8 = Object.assign({}, POS3, { ndajfolje: ["shpejt", "sot", "këtu", "ngadalë", "nesër", "atje", "mirë", "dje"], përemër: ["unë", "ti", "ai", "ne", "ky", "kush", "ato", "ju"], numëror: ["tre", "i pesti", "njëqind", "dhjetë", "e dyta", "njëzet"], parafjalë: ["në", "me", "për", "mbi", "nën", "te"], lidhëz: ["dhe", "ose", "por", "sepse", "nëse", "edhe pse"], pasthirrmë: ["oh", "ah", "uf", "bravo", "ua", "ej"] });
  const VERBS = [["punoj", "punova", "punoja", "kam punuar", "kisha punuar", "do të punoj"], ["mësoj", "mësova", "mësoja", "kam mësuar", "kisha mësuar", "do të mësoj"], ["lexoj", "lexova", "lexoja", "kam lexuar", "kisha lexuar", "do të lexoj"], ["shkruaj", "shkrova", "shkruaja", "kam shkruar", "kisha shkruar", "do të shkruaj"], ["këndoj", "këndova", "këndoja", "kam kënduar", "kisha kënduar", "do të këndoj"], ["luaj", "luajta", "luaja", "kam luajtur", "kisha luajtur", "do të luaj"], ["vrapoj", "vrapova", "vrapoja", "kam vrapuar", "kisha vrapuar", "do të vrapoj"], ["ndihmoj", "ndihmova", "ndihmoja", "kam ndihmuar", "kisha ndihmuar", "do të ndihmoj"]];
