    kohet3: () => L("Koha e foljes", () => repeat(6, () => { const v = pick(VERBS); const i = pick([0, 1, 5]); const forms = { 0: v[0], 1: v[1], 5: v[5] }; return { q: `"Unë ${forms[i]}" është në kohën:`, opts: shuffle(["e tashme", "e kryer e thjeshtë", "e ardhme"]), ans: TENSES[i], hint: "Tani? Dje? Nesër?" }; })),
