    javaMuajt: () => L("Ditët e javës dhe muajt", () => { const D = ["e hënë", "e martë", "e mërkurë", "e enjte", "e premte", "e shtunë", "e diel"]; const M = ["janari", "shkurti", "marsi", "prilli", "maji", "qershori", "korriku", "gushti", "shtatori", "tetori", "nëntori", "dhjetori"]; return repeat(6, () => { if (Math.random() < 0.5) { const i = R(0, 6); const GEN = ["së hënës", "së martës", "së mërkurës", "së enjtes", "së premtes", "së shtunës", "së dielës"]; return { q: `Cila ditë vjen pas ${GEN[i]}?`, opts: optsWith(D[(i + 1) % 7], D, 3), ans: D[(i + 1) % 7], hint: D.join(", ") }; } const i = R(0, 11); return { q: `Cili muaj vjen pas ${M[i].replace(/i$/, "it")}?`, opts: optsWith(M[(i + 1) % 12], M, 3), ans: M[(i + 1) % 12], hint: M.join(", ") }; }); }),
